#!/usr/bin/env python3
"""Build a self-contained, Persian, page-designed implementation report."""
from pathlib import Path
import base64
import html
import json

ROOT = Path(__file__).resolve().parent.parent
OUT = ROOT / 'docs/keepet-implementation-report-fa.html'
COMMIT = 'fb51cea'
REPO = 'https://github.com/kasraabo/keepet'

def esc(s): return html.escape(str(s), quote=True)
def fa(n): return str(n).translate(str.maketrans('0123456789', '۰۱۲۳۴۵۶۷۸۹'))
def p(s): return '<p>'+s+'</p>'
def h(s): return '<h3>'+s+'</h3>'
def items(*ss): return '<ul>'+''.join('<li>'+s+'</li>' for s in ss)+'</ul>'
def box(title, s, cls=''): return '<aside class="note '+cls+'"><b>'+title+'</b>'+p(s)+'</aside>'
def cards(*pairs): return '<div class="cards">'+''.join('<div class="card"><h3>'+a+'</h3><p>'+b+'</p></div>' for a,b in pairs)+'</div>'
def table(headers, rows): return '<table><thead><tr>'+''.join('<th>'+x+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+x+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table>'
def flow(*steps): return '<div class="flow">'+''.join('<div><span>'+fa(i+1)+'</span><b>'+s+'</b></div>' for i,s in enumerate(steps))+'</div>'
def route(label, path): return '<a class="route" href="https://keepet.ir'+esc(path)+'"><b>'+label+'</b><code>'+esc(path)+'</code></a>'
def routes(*pairs): return '<div class="routes">'+''.join(route(*pair) for pair in pairs)+'</div>'
def ref(label, file): return '<a class="reference" href="'+REPO+'/blob/'+COMMIT+'/docs/'+file+'">'+label+' ↗</a>'

pages=[]
def page(id, chapter, title, intro, body, refs=()):
    pages.append(dict(id=id,chapter=chapter,title=title,intro=intro,body=body,refs=refs))

